import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.ArrayDeque
import kotlin.math.sqrt

class Scan {
    private val buffer: ArrayDeque<String> = ArrayDeque()
    private val reader = BufferedReader(InputStreamReader(System.`in`))

    fun <T> next(parse: (String) -> T): T {
        while (true) {
            val token = buffer.pollFirst()
            if (token != null) {
                return parse(token)
            }
            val line = reader.readLine() ?: throw RuntimeException("Fail to read")
            buffer.addAll(line.split("\\s+".toRegex()).filter { it.isNotEmpty() })
        }
    }
}

fun isPrime(x: Int): Boolean {
    if (x < 2) return false
    val limit = sqrt(x.toDouble()).toInt()
    for (i in 2..limit) {
        if (x % i == 0) {
            return false
        }
    }
    return true
}

fun nextPrime(x: Int): Int {
    var aux = x + 1
    while (!isPrime(aux)) {
        aux++
    }
    return aux
}

fun _main() {
    val scan = Scan()
    val n: Int = scan.next { it.toInt() }
    val m: Int = scan.next { it.toInt() }
    val result = nextPrime(n) == m
    println(if (result) "YES" else "NO")
}

fun main() {
    val thread = Thread(null, { _main() }, "main", 1 shl 23)
    thread.start()
    thread.join()
}

